import { readFileSync } from "node:fs";
import { parseDispatchEmail } from "./src/providers/email.ts";

function bodyOf(raw) {
  const split = raw.split(/\r?\n\r?\n/);
  return split.length > 1 ? split.slice(1).join("\n") : raw;
}
const oldTrack = /(?:tracking(?:\s+id|\s+number)?|gu[ií]a|c[oó]digo de seguimiento|rastreo)\s*[:#]?\s*([A-Z0-9-]{8,40})/i;
const oldCarrier = /(?:carrier|transportadora|enviado con|shipped with)\s*[:#]?\s*([A-Za-z][A-Za-z0-9 .'"'"'-]{1,40})/i;

for (const f of ["amazon.txt","mercadolibre.txt","ebay.txt","alibaba.txt","homecenter.txt","../harness/regresion/reenviado-mercadolibre.txt"]) {
  const path = f.startsWith("..") ? f.slice(3) : "fixtures/correos/"+f;
  const raw = readFileSync(path, "utf8");
  const text = bodyOf(raw);
  const now = parseDispatchEmail(raw);
  const oldT = text.match(oldTrack)?.[1]?.trim() ?? null;
  const oldC = text.match(oldCarrier)?.[1]?.trim() ?? null;
  const same = !("error" in now) && now.trackingNumber === oldT && (now.carrier ?? null) === oldC;
  console.log(f, same ? "IGUAL" : "CAMBIO", "old", oldT, oldC, "new", "error" in now ? now : now.trackingNumber, now.carrier);
}
'

